"""Standalone AnomaVision light-mode dashboard server.

Run from the project root:
    python anomavision_dashboard.py

The server serves the embedded dashboard UI and exposes project files such as
``drift/drift_status.json`` to the browser. It uses only the Python standard
library, opens the default browser automatically, and does not require Gradio.
"""

from __future__ import annotations

import base64
import json
import logging
import os
import re
import threading
import webbrowser
from http import HTTPStatus
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote, urlparse

HOST = os.getenv("ANOMAVISION_DASHBOARD_HOST", "127.0.0.1")
PORT = int(os.getenv("ANOMAVISION_DRIFT_DASHBOARD_PORT", "7860"))
ROOT = Path(os.getenv("ANOMAVISION_PROJECT_ROOT", os.getcwd())).resolve()
DASHBOARD_PATH = "/anomavision_dashboard.html"
HTML = base64.b64decode(
    ""
)


class DashboardHandler(SimpleHTTPRequestHandler):
    """Serve the dashboard plus project-relative status and image files."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(ROOT), **kwargs)

    def do_GET(self):  # noqa: N802
        route = urlparse(self.path).path
        if route in {"/", "", DASHBOARD_PATH}:
            self._send_dashboard()
            return
        if route == "/api/localizations":
            self._send_localizations()
            return
        if route == "/api/samples":
            self._send_samples()
            return
        if route == "/health":
            status_path = os.getenv(
                "ANOMAVISION_DRIFT_STATUS_FILE", "drift/drift_status.json"
            )
            status_path_obj = Path(status_path).expanduser()
            if not status_path_obj.is_absolute():
                status_path_obj = ROOT / status_path_obj
            payload = json.dumps(
                {
                    "ok": True,
                    "dashboard": "anomavision",
                    "project_root": str(ROOT),
                    "status_file": str(status_path_obj.resolve()),
                }
            ).encode("utf-8")
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)
            return
        if route == "/shutdown":
            # Local-only server: allow the CLI to replace a stale dashboard
            # process when it belongs to another project/status file.
            payload = b'{"ok":true,"shutting_down":true}'
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)
            threading.Thread(target=self.server.shutdown, daemon=True).start()
            return
        # SimpleHTTPRequestHandler safely serves drift/drift_status.json,
        # configured images, and other local project assets.
        super().do_GET()

    def _image_root(self):
        configured = os.getenv("ANOMAVISION_DRIFT_IMAGE_PATH")
        if configured:
            path = Path(configured).expanduser()
            return path if path.is_absolute() else ROOT / path
        config = ROOT / os.getenv("ANOMAVISION_DRIFT_CONFIG", "config.yml")
        if config.exists():
            text = config.read_text(encoding="utf-8", errors="ignore")
            match = re.search(
                r"^\s*img_path\s*:\s*[\"']?([^\"'\n#]+)", text, re.MULTILINE
            )
            if match:
                path = Path(match.group(1).strip()).expanduser()
                return path if path.is_absolute() else config.parent / path
        return None

    def _send_samples(self):
        """Return recent production input images from config.yml img_path."""
        root = self._image_root()
        allowed = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}
        paths = []
        if root and root.exists():
            paths = (
                [root]
                if root.is_file()
                else [p for p in root.rglob("*") if p.is_file()]
            )
        paths = sorted(
            (p for p in paths if p.suffix.lower() in allowed),
            key=lambda p: str(p).lower(),
        )[-12:]
        items = [
            {"name": p.name, "url": "/" + p.relative_to(ROOT).as_posix()}
            for p in paths
            if ROOT in p.parents or p == ROOT
        ]
        payload = json.dumps(items).encode("utf-8")
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def _send_localizations(self):
        """Return the newest saved visualization images for the browser gallery."""
        root = ROOT / "visualizations"
        allowed = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}
        items = []
        if root.exists():
            for path in root.rglob("*"):
                if path.is_file() and path.suffix.lower() in allowed:
                    relative = path.relative_to(ROOT).as_posix()
                    items.append({"name": path.name, "url": "/" + relative})
        # Keep one representative overlay per source image and show only the newest four.
        unique = {}
        for item in sorted(items, key=lambda item: item["name"].lower(), reverse=True):
            key = re.sub(
                r"(?:_heatmap|_overlay|_mask|_visualization|_viz)$",
                "",
                Path(item["name"]).stem,
                flags=re.IGNORECASE,
            ).lower()
            unique.setdefault(key, item)
        items = list(unique.values())[:4]
        payload = json.dumps(items).encode("utf-8")
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def _send_dashboard(self):
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(HTML)))
        self.end_headers()
        self.wfile.write(HTML)

    def log_message(self, fmt, *args):
        logging.info("%s - %s", self.address_string(), fmt % args)


def serve(*, open_browser: bool = True) -> None:
    """Start the dashboard server and keep it alive until interrupted."""
    logging.basicConfig(
        level=os.getenv("ANOMAVISION_LOG_LEVEL", "INFO"),
        format="[AnomaVision dashboard] %(message)s",
    )
    server = ThreadingHTTPServer((HOST, PORT), DashboardHandler)
    url = f"http://{HOST}:{PORT}{DASHBOARD_PATH}"
    logging.info("Project root: %s", ROOT)
    logging.info("Dashboard: %s", url)
    if open_browser:
        threading.Timer(0.6, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        logging.info("Stopping dashboard")
    finally:
        server.server_close()


if __name__ == "__main__":
    serve()
